import{z as B,x as s,o as r,c as p,q as n,j as o,D as E,d as t,s as A,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"预防性储蓄与缓冲存量","description":"","frontmatter":{"title":"预防性储蓄与缓冲存量","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/precautionary-buffer-stock.md","filePath":"econ/precautionary-buffer-stock.md","lastUpdated":1791063341000}'),d={name:"econ/precautionary-buffer-stock.md"};function m(u,a,c,D,f,C){const l=s("Mermaid");return r(),p("div",null,[a[2]||(a[2]=n('<h1 id="预防性储蓄与缓冲存量" tabindex="-1">预防性储蓄与缓冲存量 <a class="header-anchor" href="#预防性储蓄与缓冲存量" aria-label="Permalink to &quot;预防性储蓄与缓冲存量&quot;">​</a></h1><div class="epigraph"><p>若边际效用凸，收入风险本身就会提高储蓄：不是为了退休，是为了给坏年景留一笔缓冲。</p><footer>—— Leland, Saving and Uncertainty: The Precautionary Demand for Saving, QJE 1968；Carroll, Buffer-Stock Saving and the Life Cycle/Permanent Income Hypothesis, QJE 1997</footer></div><p><a href="/econ/permanent-income">上一课</a>的确定性等价把风险关掉。本课缺口是：当 \\(u&#39;&#39;&#39;\\gt 0\\)（谨慎）且劳动收入不可完全保险，欧拉里多出一项预防性溢价，目标资产变成缓冲存量。不重写 Friedman 的永久/暂时切法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>二次效用使期望边际效用等于边际效用的期望，收入方差不进消费。Leland（1968）指出：凸的 \\(u&#39;\\) 让风险提高 \\(\\mathbb{E}u&#39;(c_{t+1})\\)，为恢复欧拉必须压低当期 \\(c\\)，即预防性储蓄。Kimball（1990）把谨慎系数 \\(-u&#39;&#39;&#39;/u&#39;&#39;\\) 从风险厌恶里拆出来。Carroll（1992, 1997）与 Deaton（1991）在借贷下限附近做成缓冲存量：人有一个目标财富–永久收入比，低于则储蓄，高于则消耗，消费对收入短期敏感，但不是 Keynes 的固定 \\(c\\)。</p><p>缺口是给 PIH 加上不可保风险，而不是重推 <a href="/econ/expected-utility">vNM</a>。伯努利 \\(u\\) 已有，只动三阶。</p><p><span class="marginnote">术语翻译：风险厌恶（\\(u&#39;&#39;\\lt 0\\)）是你愿意付多少钱消除一个已知风险；谨慎（\\(u&#39;&#39;&#39;\\gt 0\\)）是「风险越大，越想先攒一笔」的额外冲动。二阶决定怕不怕，三阶决定要不要提前备粮。二次效用怕归怕、不备粮，这正是上一课确定性等价能成立的原因。</span></p><p><span class="marginnote">缓冲存量需要不耐烦（\\(\\beta(1+r)\\lt 1\\)）或借贷约束，否则财富会漂到无限来自保。Carroll 把不耐烦与失业风险焊在一起，得到稳定的目标比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>劳动收入含持久与暂时冲击，债券利率外生，可能有 \\(a_{t+1}\\ge 0\\)。欧拉在约束不绑定时成立，绑定时变不等式。政策函数 \\(c(x)\\) 对现金 \\(x\\) 凹：穷时几乎吃掉收入，富时接近 PIH。目标缓冲使财富分布集中在约束附近，加总后仍有正的短期 MPC。</p>',10)),(r(),o(i,null,{default:E(()=>[A(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIH%5B%22%E7%A1%AE%E5%AE%9A%E6%80%A7%E7%AD%89%E4%BB%B7%20PIH%22%5D%20--%3E%20PRU%5B%22u'''%3E0%20%E4%B8%8E%E4%B8%8D%E5%8F%AF%E4%BF%9D%E6%94%B6%E5%85%A5%22%5D%0A%20%20PRU%20--%3E%20PREC%5B%22%E9%A2%84%E9%98%B2%E6%80%A7%3A%20%E5%8E%8B%E4%BD%8E%E5%BD%93%E6%9C%9F%20c%22%5D%0A%20%20PREC%20--%3E%20BUF%5B%22%E7%9B%AE%E6%A0%87%E8%B4%A2%E5%AF%8C-%E6%94%B6%E5%85%A5%E6%AF%94%22%5D%0A%20%20BUF%20--%3E%20MPC%5B%22%E7%BA%A6%E6%9D%9F%E9%99%84%E8%BF%91%E9%AB%98%20MPC%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"本课不估计谨慎系数。也不把股票当缓冲：参与之谜后课再写；这里的资产是无风险或广义流动性财富。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是边际效用在低收入状态特别高。无法用 Arrow–Debreu 证券把劳动收入在状态间挪走时，唯一的自保是先存一笔。冲击到来，缓冲下降，MPC 上升，消费看起来「过度敏感」——下一课把这句话变成对流动性约束的检验。增长与退休仍按 LCH 提供慢变量；缓冲是快变量，对年收入波动作出反应。",-1)),a[6]||(a[6]=e("p",null,"缓冲存量绕着目标比涨落，消费与 MPC 随位置切换：",-1)),(r(),o(i,null,{default:E(()=>[A(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%9B%AE%E6%A0%87%E8%B4%A2%E5%AF%8C-%E6%94%B6%E5%85%A5%E6%AF%94%22%5D%20--%3E%20LO%5B%22%E7%BC%93%E5%86%B2%E4%BD%8E%E4%BA%8E%E7%9B%AE%E6%A0%87%EF%BC%9A%E5%9D%8F%E5%B9%B4%E6%99%AF%22%5D%0A%20%20LO%20--%3E%20S%5B%22%E5%A4%9A%E5%AD%98%E5%B0%91%E8%8A%B1%EF%BC%9A%E6%B6%88%E8%B4%B9%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20T%20--%3E%20HI%5B%22%E7%BC%93%E5%86%B2%E9%AB%98%E4%BA%8E%E7%9B%AE%E6%A0%87%EF%BC%9A%E5%A5%BD%E5%B9%B4%E6%99%AF%22%5D%0A%20%20HI%20--%3E%20C%5B%22%E5%A4%9A%E8%8A%B1%E5%B0%91%E5%AD%98%EF%BC%9A%E6%B6%88%E8%B4%B9%E6%8A%AC%E9%AB%98%22%5D%0A%20%20SH%5B%22%E5%A4%B1%E4%B8%9A%E7%AD%89%E5%A4%A7%E5%86%B2%E5%87%BB%E5%88%B0%E6%9D%A5%22%5D%20--%3E%20LO2%5B%22%E5%8A%A8%E7%94%A8%E7%BC%93%E5%86%B2%EF%BC%9A%E8%B4%A2%E5%AF%8C%E4%B8%8B%E9%99%8D%22%5D%0A%20%20LO2%20--%3E%20R%5B%22%E6%94%B6%E5%85%A5%E6%81%A2%E5%A4%8D%E5%90%8E%E9%80%90%E6%AD%A5%E5%9B%9E%E8%A1%A5%22%5D%0A%20%20R%20--%3E%20T%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p><span class="marginnote">数字实例：月收入 8000 元、目标缓冲为 3 个月收入即 24000 元。缓冲只剩 12000 元时低于目标，每月只敢花 6500、存 1500；缓冲涨过 36000 元就敢多花。同一个收入，消费随「离目标多远」摆动——这就是约束附近高 MPC 的来源，也是消费「过度敏感」的微观版本。</span></p><p>与<a href="/econ/equity-premium-puzzle">股权溢价</a>的接口：总量消费仍然平滑，因为缓冲在家庭之间对冲特异风险；谜用的是加总 \\(c\\)，不是否定微观预防性储蓄。</p><p>Kimball 的谨慎与 Arrow–Pratt 的厌恶不是同一阶：厌恶由 \\(u&#39;&#39;\\) 管对已知风险的价格，谨慎由 \\(u&#39;&#39;&#39;\\) 管「要不要先存一笔」。二次效用厌恶仍在，预防性为零——这正是 PIH 确定性等价能写出来的原因。Carroll 的目标比把不耐烦与失业风险焊死，避免财富漂到无限；没有这条，预防性储蓄只有水平，没有缓冲存量的均值回复。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>完全市场或可对冲的收入风险把预防性项关掉。习惯形成改的是 \\(u\\) 的状态变量，与谨慎不同。现时偏差也会提高流动资产需求，但动机是自我控制而非 \\(u&#39;&#39;&#39;\\)。本课不把三者混成一个「储蓄高」的故事。</p><p><span class="marginnote">常见误区：把缓冲储蓄读成「人变得更怕风险」。风险厌恶是二阶属性，没有变；变的是三阶谨慎遇上不可保的收入风险，使「先存一笔」变得划算。若市场能对冲收入风险，这一项整个消失，行为回到 PIH。</span></p><p>后课默认：说到缓冲存量，指谨慎加约束下的目标财富；说到过度敏感，先问是不是约束绑住了欧拉。</p><p>目标财富–收入比把预防性储蓄从「永远更高」变成对冲击的均值回复。</p><p>特异风险在加总后可对冲，故微观缓冲与总量消费平滑可以同时成立。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>谨慎使收入风险进入储蓄，确定性等价失败。</li><li>缓冲存量：目标财富–收入比，约束附近 MPC 高。</li><li>不重写 PIH 的永久成分，只加上不可保风险。</li><li>谨慎是三阶，厌恶是二阶，二次效用关掉本课。</li><li>约束附近的高 MPC 接到下一课过度敏感。</li><li>出处：Leland, <em>QJE</em> 1968；Kimball, <em>Econometrica</em> 1990；Deaton, <em>Econometrica</em> 1991；Carroll, <em>QJE</em> 1997。</li></ul>',11))])}const b=B(d,[["render",m]]);export{h as __pageData,b as default};
